package ai.cortex.core

/** One row of the EMV tag dictionary. */
data class EmvTagInfo(
    val tag: String,
    val name: String,
    val kernel: String,
    val source: String,
    val format: String,
    val template: String,
    val length: String,
    val description: String,
)

