    private val byTag: Map<String, List<EmvTagInfo>> = all.groupBy { it.tag }

    fun lookup(tag: String): List<EmvTagInfo> = byTag[tag.uppercase()] ?: emptyList()

    /** The generic EMV name, or the first kernel-specific one. */
    fun name(tag: String): String? = lookup(tag).let { l -> (l.firstOrNull { it.kernel == "EMV" } ?: l.firstOrNull())?.name }

    fun kernels(): List<String> = all.map { it.kernel }.distinct().sortedBy { if (it == "EMV") "" else it }

    fun search(query: String, kernel: String? = null): List<EmvTagInfo> {
        val q = query.trim().lowercase()
        return all.filter { t ->
            (kernel == null || kernel == "All" || t.kernel.equals(kernel, ignoreCase = true)) &&
                (q.isEmpty() || t.tag.lowercase().contains(q) || t.name.lowercase().contains(q) || t.description.lowercase().contains(q))
        }
    }
